/* Original script block 1 */
const drawer = document.getElementById('drawer');
const backdrop = document.getElementById('drawerBackdrop');
const menuBtn = document.getElementById('menuBtn');
const menuTab = document.getElementById('menuTab');
const categoryTab = document.getElementById('categoryTab');
const menuPanel = document.getElementById('menuPanel');
const categoryPanel = document.getElementById('categoryPanel');
function openDrawer(){
  drawer.classList.add('open');
  backdrop.classList.add('show');
  drawer.setAttribute('aria-hidden','false');
}
function closeDrawer(){
  drawer.classList.remove('open');
  backdrop.classList.remove('show');
  drawer.setAttribute('aria-hidden','true');
}
function switchTab(which){
  const category = which === 'category';
  menuTab.classList.toggle('active', !category);
  categoryTab.classList.toggle('active', category);
  menuPanel.hidden = category;
  categoryPanel.hidden = !category;
}
menuBtn.addEventListener('click', openDrawer);
backdrop.addEventListener('click', closeDrawer);
menuTab.addEventListener('click', () => switchTab('menu'));
categoryTab.addEventListener('click', () => switchTab('category'));
document.querySelectorAll('.drawer-link').forEach(link => {
  link.addEventListener('click', e => {
    e.preventDefault();
    const panel = link.closest('.drawer-panel');
    panel.querySelectorAll('.drawer-link').forEach(x => x.classList.remove('selected'));
    link.classList.add('selected');
  });
});
document.addEventListener('keydown', e => { if(e.key === 'Escape') closeDrawer(); });
;

