/* homepage-scroll-animations-js */
(function(){
  const sectionSelectors = [
    '.why-choose',
    '.home-categories',
    '.best-sellers',
    '.smartcare-section',
    '.cocco-excellence',
    '.parents-testimonials',
    '.blog-topics',
    '.faq-section',
    '.community',
    '.newsletter-section',
    '.cocco-footer'
  ];

  const groupSelectors = [
    '.why-choose-cards',
    '.home-categories-grid',
    '.best-sellers-grid',
    '.cocco-values',
    '.blog-grid',
    '.faq-list',
    '.community-grid'
  ];

  sectionSelectors.forEach(function(selector){
    document.querySelectorAll(selector).forEach(function(el){
      el.classList.add('scroll-reveal');
    });
  });

  groupSelectors.forEach(function(selector){
    document.querySelectorAll(selector).forEach(function(el){
      el.classList.add('scroll-reveal-group');
    });
  });

  if(!('IntersectionObserver' in window)){
    document.querySelectorAll('.scroll-reveal,.scroll-reveal-group')
      .forEach(function(el){el.classList.add('is-visible');});
    return;
  }

  const observer = new IntersectionObserver(function(entries){
    entries.forEach(function(entry){
      if(entry.isIntersecting){
        entry.target.classList.add('is-visible');
        observer.unobserve(entry.target);
      }
    });
  },{
    threshold:0.12,
    rootMargin:'0px 0px -7% 0px'
  });

  document.querySelectorAll('.scroll-reveal,.scroll-reveal-group')
    .forEach(function(el){observer.observe(el);});
})();
;

/* product-color-slider-script */
(function(){
  const images=[...document.querySelectorAll('.product-color-image')];
  const dots=[...document.querySelectorAll('.product-color-dot')];
  if(!images.length||!dots.length)return;

  let current=Math.max(0,images.findIndex(el=>el.classList.contains('is-active')));
  let timer;
  let settleTimer;
  let locked=false;

  function clean(el){
    el.classList.remove('from-next','from-prev','is-leaving-next','is-leaving-prev','is-settled');
  }

  function show(index, direction){
    if(index===current || locked)return;
    locked=true;
    clearTimeout(settleTimer);

    const old=current;
    const next=images[index];
    const prev=images[old];
    const dir=direction || ((index-old+images.length)%images.length <= images.length/2 ? 'next' : 'prev');

    images.forEach(clean);
    next.classList.add(dir==='next'?'from-next':'from-prev');
    next.classList.remove('is-active');

    // force a paint so the entrance pose is visible before activation
    void next.offsetWidth;

    prev.classList.remove('is-active');
    prev.classList.add(dir==='next'?'is-leaving-next':'is-leaving-prev');
    next.classList.add('is-active');
    next.classList.remove('from-next','from-prev');

    dots.forEach((el,i)=>el.classList.toggle('is-active',i===index));
    current=index;

    settleTimer=setTimeout(()=>{
      images.forEach((el,i)=>{
        clean(el);
        if(i===current){el.classList.add('is-active','is-settled')}
        else el.classList.remove('is-active');
      });
      locked=false;
    },1100);
  }

  function restart(){
    clearInterval(timer);
    timer=setInterval(()=>show((current+1)%images.length,'next'),4300);
  }

  images.forEach((el,i)=>{
    clean(el);
    el.classList.toggle('is-active',i===current);
  });
  setTimeout(()=>images[current].classList.add('is-settled'),900);

  dots.forEach((dot,i)=>dot.addEventListener('click',()=>{
    if(i===current)return;
    const forward=(i-current+images.length)%images.length;
    const dir=forward<=images.length/2?'next':'prev';
    show(i,dir);
    restart();
  }));

  restart();
})();
;

/* scroll-reveal-animation-script */
(function(){
  function mark(elements, mode, baseDelay, step){
    [...elements].forEach((el,i)=>{
      el.classList.add('reveal-on-scroll');
      if(mode) el.classList.add(mode);
      el.style.setProperty('--reveal-delay', (baseDelay + i*step) + 'ms');
    });
  }

  // Hero opens once on page load.
  const heroCopy=document.querySelector('.product-hero-copy');
  if(heroCopy) heroCopy.classList.add('hero-intro-reveal');

  // Section heading, then cards one-by-one.
  mark(document.querySelectorAll('.why-choose-header'),'reveal-scale',0,0);
  mark(document.querySelectorAll('.why-card'),'reveal-on-scroll',80,150);

  // Product introduction: title → specifications → buttons → product showcase.
  mark(document.querySelectorAll('.product-intro-copy > h2'),'reveal-left',0,0);
  mark(document.querySelectorAll('.product-spec-item'),'reveal-left',80,130);
  mark(document.querySelectorAll('.product-intro-actions .intro-btn'),'reveal-left',100,120);
  mark(document.querySelectorAll('.product-color-showcase'),'reveal-right',140,0);

  // Unique product section: heading first, then each benefit.
  mark(document.querySelectorAll('.product-unique-header'),'reveal-scale',0,0);
  mark(document.querySelectorAll('.unique-item'),'reveal-on-scroll',80,130);

  // Related products: heading first, then cards one by one, then CTA.
  mark(document.querySelectorAll('.related-products-header'),'reveal-scale',0,0);
  mark(document.querySelectorAll('.related-product-card'),'reveal-on-scroll',70,110);
  mark(document.querySelectorAll('.related-products-action'),'reveal-on-scroll',100,0);

  // Footer reveals in sequence as the user reaches the bottom.
  mark(document.querySelectorAll('.footer-grid > *'),'reveal-on-scroll',0,110);
  mark(document.querySelectorAll('.footer-bottom'),'reveal-on-scroll',80,0);

  const items=[...document.querySelectorAll('.reveal-on-scroll')];
  if(!items.length) return;

  if(!('IntersectionObserver' in window)){
    items.forEach(el=>el.classList.add('is-revealed'));
    return;
  }

  const observer=new IntersectionObserver((entries,obs)=>{
    entries.forEach(entry=>{
      if(entry.isIntersecting){
        entry.target.classList.add('is-revealed');
        obs.unobserve(entry.target);
      }
    });
  },{
    threshold:0.14,
    rootMargin:'0px 0px -8% 0px'
  });

  items.forEach(el=>observer.observe(el));
})();
;

