/* store-finder-demo-script */
(function(){
 const trigger=document.getElementById('particuliersButton');
 const overlay=document.getElementById('storeFinderOverlay');
 const panel=document.getElementById('storeFinderPanel');
 const close=document.getElementById('storeFinderClose');
 const locate=document.getElementById('storeFinderLocation');
 const status=document.getElementById('storeFinderStatus');
 const results=document.getElementById('storeFinderResults');
 const demoLabel=document.getElementById('storeFinderDemoLabel');
 if(!trigger||!overlay||!panel)return;
 function openFinder(e){
   if(e)e.preventDefault();
   overlay.hidden=false;
   if(results) results.hidden=true;
   if(demoLabel) demoLabel.hidden=true;
   if(status) status.textContent='';
   document.body.classList.add('store-finder-open');
   setTimeout(()=>close&&close.focus(),0);
 }
 function closeFinder(){
   overlay.hidden=true;
   document.body.classList.remove('store-finder-open');
   trigger.focus();
 }
 trigger.addEventListener('click',openFinder);
 close&&close.addEventListener('click',closeFinder);
 overlay.addEventListener('click',(e)=>{if(e.target===overlay)closeFinder();});
 document.addEventListener('keydown',(e)=>{if(e.key==='Escape'&&!overlay.hidden)closeFinder();});
 function distanceKm(lat1,lng1,lat2,lng2){
   const R=6371;
   const toRad=(v)=>v*Math.PI/180;
   const dLat=toRad(lat2-lat1);
   const dLng=toRad(lng2-lng1);
   const a=Math.sin(dLat/2)**2 + Math.cos(toRad(lat1))*Math.cos(toRad(lat2))*Math.sin(dLng/2)**2;
   return 2*R*Math.asin(Math.sqrt(a));
 }
 locate&&locate.addEventListener('click',()=>{
   if(!window.isSecureContext){
     status.textContent='La localisation du téléphone est bloquée dans cet aperçu. Ouvrez la page sur votre site en HTTPS pour utiliser le GPS.';
     return;
   }
   if(!navigator.geolocation){
     status.textContent='La localisation n’est pas disponible sur ce navigateur.';
     return;
   }
   status.textContent='Recherche de votre position…';
   locate.disabled=true;
   navigator.geolocation.getCurrentPosition(
     (position)=>{
       const lat=position.coords.latitude;
       const lng=position.coords.longitude;
       panel.dataset.userLat=lat.toFixed(6);
       panel.dataset.userLng=lng.toFixed(6);
       const cards=[...document.querySelectorAll('#storeFinderResults .store-card')];
       cards.forEach(card=>{
         const cLat=parseFloat(card.dataset.lat);
         const cLng=parseFloat(card.dataset.lng);
         const d=distanceKm(lat,lng,cLat,cLng);
         card.dataset.distance=d;
         const distanceEl=card.querySelector('.store-card-side strong');
         if(distanceEl) distanceEl.textContent=d<10 ? d.toFixed(1).replace('.',',')+' km' : Math.round(d)+' km';
       });
       cards.sort((a,b)=>parseFloat(a.dataset.distance)-parseFloat(b.dataset.distance));
       cards.forEach(card=>results.appendChild(card));
       if(results) results.hidden=false;
       if(demoLabel) demoLabel.hidden=false;
       status.textContent='Position détectée ✓ Voici les points de vente les plus proches.';
       locate.disabled=false;
     },
     (error)=>{
       locate.disabled=false;
       if(error.code===1){
         status.textContent='Accès à la position refusé. Les itinéraires restent disponibles pour chaque pharmacie.';
       }else if(error.code===2){
         status.textContent='Impossible de déterminer votre position. Vérifiez le GPS et la connexion internet, puis réessayez.';
       }else{
         status.textContent='La localisation a pris trop de temps. Réessayez dans un endroit avec un meilleur signal GPS.';
       }
     },
     {enableHighAccuracy:true,timeout:20000,maximumAge:0}
   );
 });
})();
;

